INSERT INTO "updateNotes" ("id", "title", "description", "category", "isVisible", "createdByUserId", "createdAt", "updatedAt") VALUES (1, 'Visão geral e metas de recebimento', 'Foram consolidados os indicadores de Meta Fiado, Meta Desafio, Ticket, inadimplência e projeções no painel de acompanhamento.', 'Metas', TRUE, NULL, '2026-08-18T12:00:00.000Z', '2026-08-18T12:00:00.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "updateNotes" ("id", "title", "description", "category", "isVisible", "createdByUserId", "createdAt", "updatedAt") VALUES (2, 'Filiais, cadastros e conversas', 'A plataforma passou a reunir filiais, contatos dos operadores, cadastros, chat geral e conversas privadas.', 'Operação', TRUE, NULL, '2026-08-19T12:00:00.000Z', '2026-08-19T12:00:00.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "updateNotes" ("id", "title", "description", "category", "isVisible", "createdByUserId", "createdAt", "updatedAt") VALUES (3, 'Plano PRO e pagamentos', 'Foram adicionados o controle de assinatura PRO, período de carência, comprovantes e pagamento automático pelo Mercado Pago.', 'Plano PRO', TRUE, NULL, '2026-08-21T12:00:00.000Z', '2026-08-21T12:00:00.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "updateNotes" ("id", "title", "description", "category", "isVisible", "createdByUserId", "createdAt", "updatedAt") VALUES (4, 'Romaneio e Matriz', 'O Romaneio com assinaturas e a Matriz consolidada de filiais passaram a estar disponíveis para a operação PRO.', 'Recursos PRO', TRUE, NULL, '2026-08-22T12:00:00.000Z', '2026-08-22T12:00:00.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "updateNotes" ("id", "title", "description", "category", "isVisible", "createdByUserId", "createdAt", "updatedAt") VALUES (5, 'Ajuda e atendimento organizado', 'O manual ganhou atendimento direto ao administrador, respostas rápidas com assunto e status manual de disponibilidade.', 'Atendimento', TRUE, NULL, '2026-08-26T09:00:00.000Z', '2026-08-26T09:00:00.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "updateNotes" ("id", "title", "description", "category", "isVisible", "createdByUserId", "createdAt", "updatedAt") VALUES (6, 'Aciona One e exportações', 'Foi incluída a ferramenta para transformar planilhas de contatos em listas revisáveis, com filtros, impressão e exportações em Excel e PDF.', 'Utilidades', TRUE, NULL, '2026-08-26T12:30:00.000Z', '2026-08-26T12:30:00.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "updateNotes" ("id", "title", "description", "category", "isVisible", "createdByUserId", "createdAt", "updatedAt") VALUES (30001, 'Botão Preencher com a matriz em ajustes', 'Com esse botão vc preenche os dados de sua filial em apenas um click!', 'Utilidades', TRUE, 1, '2026-09-02T21:55:48.000Z', '2026-09-02T21:56:19.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "updateNotes" ("id", "title", "description", "category", "isVisible", "createdByUserId", "createdAt", "updatedAt") VALUES (60001, 'Correção em Diaria', '- Correção dos valores diários (recebimento por dia)

- Acrescentados mais escolha no modo manual

- Atualizar a pagina F5', 'Geral', TRUE, 1, '2026-09-09T14:54:25.000Z', '2026-09-09T14:55:47.000Z') ON CONFLICT DO NOTHING;
